		ret.add(Tab4Panel);
		ret.add(Tab5Panel);
		ret.add(Tab6Panel);
		ret.add(Tab7Panel);
		ret.add(Tab8Panel);
		ret.add(CndPanel);
		ret.add(Cnd2Panel);
		ret.add(Cnd3Panel);
		ret.add(Cnd4Panel);
		ret.add(Cnd5Panel);
		ret.add(Cnd6Panel);
		ret.add(Cnd7Panel);
		ret.add(Cnd8Panel);
		ret.add(CtrlPanel);
		ret.add(RPnlPanel);
		ret.add(BulkSetPanel);
		ret.add(RsltPanel);
		ret.add(BtnPanel);
		ret.add(EastBtnPanel);
		return ret;
